insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('95a36237-15cb-5de3-a96c-f7b1828d3cfc', 'drill-rw-conventions', 'Grammar: Standard English Conventions', 'Boundaries, agreement, modifiers, parallelism', 'drill', 'rw', 'standard_conventions', 'mixed', 'Sentence boundaries and punctuation, subject-verb agreement, verb tense, dangling modifiers and parallel structure.', 12) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('f6a28d3e-5c4a-5add-a40b-23c6ebbe04dd', '95a36237-15cb-5de3-a96c-f7b1828d3cfc', 1, 'Grammar: Standard English Conventions', 'rw', 600) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('4e53f2e8-5395-506a-ab68-531cb4446ec6', 'f6a28d3e-5c4a-5add-a40b-23c6ebbe04dd', 1, 'standard_conventions', 'boundaries', 'easy', 'mc', 'The bridge was closed for repairs in June _______ it reopened to traffic in October.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", and"},{"key":"B","text":", "},{"key":"C","text":" and,"},{"key":"D","text":"and, "}]'::jsonb, 'A', null, 'Two independent clauses joined by ''and'' take a comma before the conjunction. Choice B leaves a comma splice, and choices C and D place the comma after the conjunction, where it does not belong.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('03225119-cf74-5db5-a4da-c9eb6d52af60', 'f6a28d3e-5c4a-5add-a40b-23c6ebbe04dd', 2, 'standard_conventions', 'form_structure_sense', 'easy', 'mc', 'The collection of letters, photographs, and railway tickets _______ kept in a single cardboard box for forty years.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"were"},{"key":"B","text":"was"},{"key":"C","text":"have"},{"key":"D","text":"are"}]'::jsonb, 'B', null, 'The subject is the singular ''collection''; the plural nouns sit inside a prepositional phrase and do not control the verb. Choice A is the trap created by the three plural nouns immediately before the blank.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('17fdc083-e517-5834-a7d6-f2ff0548d37e', 'f6a28d3e-5c4a-5add-a40b-23c6ebbe04dd', 3, 'standard_conventions', 'boundaries', 'easy', 'mc', 'Because the ferry runs only twice a day _______ visitors usually stay overnight.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":"; "},{"key":"C","text":": "},{"key":"D","text":" "}]'::jsonb, 'A', null, 'A dependent clause beginning with ''Because'' is separated from the main clause by a comma. A semicolon or colon would require an independent clause before it, which the ''Because'' clause is not.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1972192f-6396-5160-a4ff-e7f12d59d723', 'f6a28d3e-5c4a-5add-a40b-23c6ebbe04dd', 4, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'The novel''s narrator describes the harbour as it looked before the war, when fishing boats _______ the entire quay.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"fill"},{"key":"B","text":"filled"},{"key":"C","text":"will fill"},{"key":"D","text":"have filled"}]'::jsonb, 'B', null, 'The clause describes a past state before the war, so the simple past ''filled'' matches the time frame set by ''as it looked before''. Choice D''s present perfect would connect the action to the present, which contradicts the past setting.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('eeb67d3f-cd84-5f2f-a7bf-6542d3e224cc', 'f6a28d3e-5c4a-5add-a40b-23c6ebbe04dd', 5, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The geologist identified the rock immediately _______ basalt, formed from lava that cooled at the surface.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":": "},{"key":"B","text":"; "},{"key":"C","text":" and "},{"key":"D","text":", and "}]'::jsonb, 'A', null, 'A colon after a complete clause introduces the identification that follows. A semicolon would need a full independent clause after it, and ''basalt, formed from lava...'' is a noun phrase.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('beb25645-40eb-578a-afaf-037f7c4d44f1', 'f6a28d3e-5c4a-5add-a40b-23c6ebbe04dd', 6, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'Walking home along the canal, _______', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"the herons were visible on the far bank."},{"key":"B","text":"there were herons on the far bank."},{"key":"C","text":"Rania counted six herons on the far bank."},{"key":"D","text":"six herons had gathered on the far bank."}]'::jsonb, 'C', null, 'The opening participial phrase must describe the person doing the walking, so the main clause has to start with a person — Rania. The other options attach the walking to herons or to nothing, leaving a dangling modifier.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c1328654-0396-574f-a136-1d678b533469', 'f6a28d3e-5c4a-5add-a40b-23c6ebbe04dd', 7, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The archive contains three unpublished scores _______ a string quartet from 1931, a set of piano preludes, and an unfinished opera.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":", "},{"key":"B","text":": "},{"key":"C","text":"; "},{"key":"D","text":", and "}]'::jsonb, 'B', null, 'A complete clause precedes a list naming its items, and a colon is the mark for that. A comma would be too weak to introduce a full list, and a semicolon signals a second independent clause that never arrives.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1f13204c-8e4d-53df-a5fe-2dc53c4d4c25', 'f6a28d3e-5c4a-5add-a40b-23c6ebbe04dd', 8, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'The training programme improved reaction time, reduced error rates, and _______', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"confidence among trainees was increased."},{"key":"B","text":"increased confidence among trainees."},{"key":"C","text":"there was an increase in trainee confidence."},{"key":"D","text":"trainees became more confident as a result."}]'::jsonb, 'B', null, 'The first two items are past-tense verbs with objects, so the third must match: ''increased confidence''. The other options switch to full clauses and break the parallel series.') on conflict (id) do nothing;
